#!/usr/bin/env python3
# generated by LLM

from __future__ import annotations

import argparse
import asyncio
import json
import os
import sys
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Sequence
from urllib.parse import unquote, urlsplit

import dotenv

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from core.r2 import AsyncR2Client

AUDIT_HOST = "img.gsgfs.moe"
IMMUTABLE_CACHE_CONTROL = "public, max-age=31536000, immutable"
DERIVED_CACHE_CONTROL = "public, max-age=604800"
IMMUTABLE_PREFIXES = ("img/", "images/raw/", "musics/")
DERIVED_PREFIXES = (
    "images/avif/",
    "images/webp/",
    "images/thumbnails/",
    "images/responsive/",
)
MAX_COPY_SIZE = 5 * 1024**3


@dataclass(frozen=True, slots=True)
class RepairCandidate:
    url: str
    key: str
    cache_control: str


@dataclass(frozen=True, slots=True)
class RepairResult:
    url: str
    key: str
    cache_control: str
    status: str
    error: str | None = None


def _utc_now_iso() -> str:
    return (
        datetime.now(timezone.utc)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z")
    )


def cache_control_for_key(key: str) -> str:
    if key.startswith(IMMUTABLE_PREFIXES):
        return IMMUTABLE_CACHE_CONTROL
    if key.startswith(DERIVED_PREFIXES):
        return DERIVED_CACHE_CONTROL
    raise ValueError(f"no cache policy is defined for object key: {key}")


def object_key_from_url(value: str) -> str:
    try:
        url = urlsplit(value)
        port = url.port
    except ValueError as exc:
        raise ValueError(f"invalid resource URL: {value}") from exc
    if (
        url.scheme != "https"
        or (url.hostname or "").lower() != AUDIT_HOST
        or port not in (None, 443)
        or url.username is not None
        or url.password is not None
        or url.query
        or url.fragment
    ):
        raise ValueError(f"resource URL is not a plain {AUDIT_HOST} URL: {value}")

    key = unquote(url.path).lstrip("/")
    path = PurePosixPath(key)
    if not key or "\x00" in key or any(part in ("", ".", "..") for part in path.parts):
        raise ValueError(f"resource URL has an unsafe object key: {value}")
    return key


def extract_candidates(report: dict) -> list[RepairCandidate]:
    resources = report.get("resources")
    if not isinstance(resources, list):
        raise ValueError("audit report does not contain a resources list")

    candidates: dict[str, RepairCandidate] = {}
    for resource in resources:
        if not isinstance(resource, dict):
            raise ValueError("audit report contains an invalid resource entry")
        if (
            resource.get("hostname") != AUDIT_HOST
            or resource.get("policyStatus") != "missing"
        ):
            continue
        url = resource.get("url")
        if not isinstance(url, str):
            raise ValueError("audit resource does not contain a valid URL")
        key = object_key_from_url(url)
        candidate = RepairCandidate(
            url=url,
            key=key,
            cache_control=cache_control_for_key(key),
        )
        previous = candidates.setdefault(key, candidate)
        if previous != candidate:
            raise ValueError(
                f"multiple resource URLs map to the same object key: {key}"
            )
    return [candidates[key] for key in sorted(candidates)]


async def repair_object(
    client: AsyncR2Client, candidate: RepairCandidate
) -> RepairResult:
    try:
        stored = await client.stat(candidate.key)
        if stored.cache_control == candidate.cache_control:
            return RepairResult(
                **asdict(candidate),
                status="already-correct",
            )
        if stored.size is not None and stored.size > MAX_COPY_SIZE:
            raise RuntimeError("object exceeds the 5 GiB CopyObject limit")
        if not stored.etag:
            raise RuntimeError("object does not have an ETag")

        await client.copy(
            candidate.key,
            candidate.key,
            cache_control=candidate.cache_control,
            metadata_directive="MERGE",
            source_if_match=stored.etag,
            destination_if_match=stored.etag,
            storage_class=stored.storage_class,
        )
        verified = await client.stat(candidate.key)
        if verified.cache_control != candidate.cache_control:
            raise RuntimeError("Cache-Control verification failed after CopyObject")
        return RepairResult(**asdict(candidate), status="updated")
    except Exception as error:
        return RepairResult(**asdict(candidate), status="failed", error=str(error))


async def repair_candidates(
    candidates: Sequence[RepairCandidate],
    *,
    apply: bool,
    client: AsyncR2Client | None = None,
    max_workers: int = 8,
) -> list[RepairResult]:
    if not apply:
        return [
            RepairResult(**asdict(candidate), status="planned")
            for candidate in candidates
        ]
    if client is None:
        raise ValueError("an R2 client is required with --apply")
    if max_workers < 1:
        raise ValueError("max_workers must be positive")

    semaphore = asyncio.Semaphore(max_workers)

    async def repair(candidate: RepairCandidate) -> RepairResult:
        async with semaphore:
            return await repair_object(client, candidate)

    return list(await asyncio.gather(*(repair(candidate) for candidate in candidates)))


def create_r2_client(
    *,
    endpoint_url: str,
    access_key_id: str,
    secret_access_key: str,
    bucket: str,
) -> AsyncR2Client:
    return AsyncR2Client(
        endpoint_url,
        access_key_id,
        secret_access_key,
        bucket,
    )


def _required(value: str | None, name: str) -> str:
    if value is None or not value.strip():
        raise ValueError(f"{name} is required with --apply")
    return value.strip()


def _positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be a positive integer") from exc
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return parsed


def parse_arguments(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Backfill Cache-Control metadata for R2 objects from a CDN audit."
    )
    parser.add_argument("report", type=Path, help="CDN audit JSON report")
    parser.add_argument(
        "--output",
        type=Path,
        help="Output prefix without .json/.purge.txt",
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Update R2 objects; without this flag only a dry run is performed",
    )
    parser.add_argument("--bucket", default=os.getenv("S3_BUCKET_NAME"))
    parser.add_argument("--endpoint-url", default=os.getenv("S3_ENDPOINT_URL"))
    parser.add_argument("--access-key-id", default=os.getenv("S3_ACCESS_KEY_ID"))
    parser.add_argument(
        "--secret-access-key", default=os.getenv("S3_SECRET_ACCESS_KEY")
    )
    parser.add_argument("--max-workers", type=_positive_int, default=8)
    return parser.parse_args(argv)


async def run(args: argparse.Namespace) -> bool:
    report_path = args.report.resolve()
    report = json.loads(report_path.read_text(encoding="utf-8"))
    candidates = extract_candidates(report)

    bucket = args.bucket
    if args.apply:
        bucket = _required(bucket, "--bucket or S3_BUCKET_NAME")
        client = create_r2_client(
            endpoint_url=_required(
                args.endpoint_url, "--endpoint-url or S3_ENDPOINT_URL"
            ),
            access_key_id=_required(
                args.access_key_id, "--access-key-id or S3_ACCESS_KEY_ID"
            ),
            secret_access_key=_required(
                args.secret_access_key,
                "--secret-access-key or S3_SECRET_ACCESS_KEY",
            ),
            bucket=bucket,
        )
        async with client:
            results = await repair_candidates(
                candidates,
                apply=True,
                client=client,
                max_workers=args.max_workers,
            )
    else:
        results = await repair_candidates(candidates, apply=False)
    counts = {
        status: sum(result.status == status for result in results)
        for status in ("planned", "updated", "already-correct", "failed")
    }
    output_prefix = (
        args.output.resolve()
        if args.output
        else report_path.with_name(f"{report_path.stem}-cache-control-repair")
    )
    output_prefix.parent.mkdir(parents=True, exist_ok=True)
    result_path = output_prefix.with_suffix(".json")
    purge_path = output_prefix.with_suffix(".purge.txt")
    result_path.write_text(
        json.dumps(
            {
                "generatedAt": _utc_now_iso(),
                "sourceReport": str(report_path),
                "host": AUDIT_HOST,
                "mode": "apply" if args.apply else "dry-run",
                "bucket": bucket if args.apply else None,
                "summary": {"candidates": len(candidates), **counts},
                "results": [asdict(result) for result in results],
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    purge_statuses = {"updated", "already-correct"} if args.apply else {"planned"}
    purge_urls = sorted(
        result.url for result in results if result.status in purge_statuses
    )
    purge_path.write_text("".join(f"{url}\n" for url in purge_urls), encoding="utf-8")

    sys.stdout.write(json.dumps({"candidates": len(candidates), **counts}, indent=2))
    sys.stdout.write(f"\nReport: {result_path}\nPurge:  {purge_path}\n")
    return counts["failed"] > 0


def main() -> None:
    dotenv.load_dotenv(Path(__file__).resolve().parents[1] / ".env")
    try:
        args = parse_arguments()
        if asyncio.run(run(args)):
            sys.exit(2)
    except Exception as error:
        print(f"error: {error}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
